/* @lc app=leetcode id=3245 lang=kotlin */ class Solution { fun bu(t: LongArray, i: Int, d: Long) = generateSequence(i) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += d } fun bq(t: LongArray, i: Int): Long = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun ar(c: LongArray, s: LongArray, len: Int, d: Int) = bu(c, len, d.toLong()).also { bu(s, len, d.toLong() * len) } fun rl(a: Int, b: Int, n: Int) = if (a == b) n else (b - a + n) % n fun addB(ts: java.util.TreeSet<Int>, c: LongArray, s: LongArray, n: Int, p: Int) = (if (ts.isEmpty()) ar(c, s, n, 1) else (ts.lower(p) ?: ts.last()).let { a -> (ts.higher(p) ?: ts.first()).let { b -> ar(c, s, rl(a, b, n), -1).also { ar(c, s, rl(a, p, n), 1) }.also { ar(c, s, rl(p, b, n), 1) } } }).also { ts.add(p) } fun remB(ts: java.util.TreeSet<Int>, c: LongArray, s: LongArray, n: Int, p: Int) = ts.remove(p).let { if (ts.isEmpty()) ar(c, s, n, -1) else (ts.lower(p) ?: ts.last()).let { a -> (ts.higher(p) ?: ts.first()).let { b -> ar(c, s, rl(a, p, n), -1).also { ar(c, s, rl(p, b, n), -1) }.also { ar(c, s, rl(a, b, n), 1) } } } } fun numberOfAlternatingGroups(colors: IntArray, queries: Array<IntArray>): List<Int> = colors.size.let { n -> colors.copyOf().let { col -> LongArray(n + 1).let { c -> LongArray(n + 1).let { s -> java.util.TreeSet<Int>().let { ts -> (0 until n).filter { col[it] == col[(it + 1) % n] }.forEach { addB(ts, c, s, n, it) }.let { queries.mapNotNull { q -> if (q[0] == 1) (if (ts.isEmpty()) n else ((bq(c, n) - bq(c, q[1] - 1)) * (1 - q[1]) + (bq(s, n) - bq(s, q[1] - 1))).toInt()) else (if (col[q[1]] == q[2]) null else listOf((q[1] - 1 + n) % n, q[1]).map { p -> p to (col[p] == col[(p + 1) % n]) }.let { before -> col.set(q[1], q[2]).let { before.forEach { (p, was) -> (col[p] == col[(p + 1) % n]).let { now -> if (now && !was) addB(ts, c, s, n, p) else if (!now && was) remB(ts, c, s, n, p) } } } }.let { null }) } } } } } } } }